const INVISIBLE = /[\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u2064\uFEFF\u{E0000}-\u{E007F}]/gu;

export const foldConfusables = (text        )         =>
  Array.from(
    text.normalize('NFKC').replace(INVISIBLE, ''),
    (char) => CONFUSABLES.get(char) ?? char,
  ).join('');
